//! 🧪️ Genuine original Host currency cannot renew itself or admit a second owner before exact receipt collection.
use super::*;
fn observe<T>(body:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(body);(value,(heap.requested_bytes,heap.released_bytes))}
#[test]
fn original_host_wake_ledger_keeps_actual_turn_exclusion_all_currencies_and_explicit_driver_return(){
 let(_,heap)=observe(||drop(vec![0u8;37]));assert_eq!(heap,(37,37));
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["policy"];let grant=RetainedCloneGrant{maximum_items:p["items"].as_u64().unwrap()as usize,maximum_copy_bytes:p["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:p["release"].as_u64().unwrap()as usize,maximum_depth:p["depth"].as_u64().unwrap()as usize};let ledger=GuestRelayWakeReceiptLedger::new();let pointer=&ledger as*const GuestRelayWakeReceiptLedger;
 let(context,heap)=observe(||ledger.checkout(7,3).unwrap());assert!(context.is_none());assert_eq!(heap,(0,0));
 assert!(ledger.begin_turn(70,grant).unwrap());let context=ledger.checkout(7,3).unwrap().unwrap();let zero=GuestRelayWakeReceipt{epoch:context.epoch,slot:7,generation:3,grant:context.grant,progress:Default::default()};let(collected,heap)=observe(||ledger.collect(&zero).unwrap());assert!(collected);assert_eq!(heap,(0,0));let returned=ledger.take_turn(70).unwrap().unwrap();assert_eq!(returned.remaining,grant);assert_eq!(returned.spent,Default::default());let(replayed,heap)=observe(||ledger.begin_turn(70,grant));assert!(replayed.is_err());assert_eq!(heap,(0,0));
 let held=ledger.original.try_lock().unwrap();let(context,heap)=observe(||ledger.checkout(7,3).unwrap());assert!(context.is_none());assert_eq!(heap,(0,0));let(collected,heap)=observe(||ledger.collect(&zero).unwrap());assert!(!collected);assert_eq!(heap,(0,0));drop(held);
 for (phase,row)in law["receipts"].as_array().unwrap().iter().enumerate(){let epoch=71+phase as u64;let(admitted,heap)=observe(||ledger.begin_turn(epoch,grant).unwrap());assert!(admitted);assert_eq!(heap,(0,0));let(context,heap)=observe(||ledger.checkout(7,3).unwrap().unwrap());assert_eq!(context,GuestRelayWakeTurnGrant{epoch,grant});assert_eq!(heap,(0,0));let(context,heap)=observe(||ledger.checkout(9,5).unwrap());assert!(context.is_none());assert_eq!(heap,(0,0));let(returned,heap)=observe(||ledger.take_turn(epoch).unwrap());assert!(returned.is_none());assert_eq!(heap,(0,0));
 let receipt=GuestRelayWakeReceipt{epoch,slot:7,generation:3,grant,progress:RetainedCloneProgress{copied_items:row["copiedItems"].as_u64().unwrap()as usize,copied_bytes:row["copiedBytes"].as_u64().unwrap()as usize,retained_capacity_bytes:row["retainedCapacityBytes"].as_u64().unwrap()as usize,released_bytes:row["releasedBytes"].as_u64().unwrap()as usize}};
 for denied in [GuestRelayWakeReceipt{epoch:epoch+1,..receipt},GuestRelayWakeReceipt{slot:9,..receipt},GuestRelayWakeReceipt{generation:5,..receipt},GuestRelayWakeReceipt{progress:RetainedCloneProgress{copied_items:2,..receipt.progress},..receipt},GuestRelayWakeReceipt{progress:RetainedCloneProgress{copied_bytes:4097,..receipt.progress},..receipt},GuestRelayWakeReceipt{progress:RetainedCloneProgress{retained_capacity_bytes:65537,..receipt.progress},..receipt},GuestRelayWakeReceipt{progress:RetainedCloneProgress{released_bytes:262145,..receipt.progress},..receipt},GuestRelayWakeReceipt{grant:RetainedCloneGrant{maximum_depth:65,..grant},..receipt}]{let(result,heap)=observe(||ledger.collect(&denied));assert!(result.is_err());assert_eq!(heap,(0,0));assert_eq!(&ledger as*const _,pointer);}
 let(collected,heap)=observe(||ledger.collect(&receipt).unwrap());assert!(collected);assert_eq!(heap,(0,0));let(duplicate,heap)=observe(||ledger.collect(&receipt));assert!(duplicate.is_err());assert_eq!(heap,(0,0));let(context,heap)=observe(||ledger.checkout(7,3).unwrap());assert!(context.is_none());assert_eq!(heap,(0,0));let(renewed,heap)=observe(||ledger.begin_turn(epoch+1,grant).unwrap());assert!(!renewed);assert_eq!(heap,(0,0));let(returned,heap)=observe(||ledger.take_turn(epoch).unwrap().unwrap());assert_eq!(heap,(0,0));assert_eq!(returned.original,grant);assert_eq!(returned.spent,receipt.progress);assert_eq!(returned.remaining.maximum_items,0);assert_eq!(returned.remaining.maximum_copy_bytes,grant.maximum_copy_bytes-receipt.progress.copied_bytes);assert_eq!(returned.remaining.maximum_capacity_bytes,grant.maximum_capacity_bytes-receipt.progress.retained_capacity_bytes);assert_eq!(returned.remaining.maximum_release_bytes,grant.maximum_release_bytes-receipt.progress.released_bytes);assert_eq!(returned.remaining.maximum_depth,grant.maximum_depth);}
 let(_,heap)=observe(||drop(ledger));assert_eq!(heap,(0,0));eprintln!("[DEBUG] actual original Host wake context2explicitdriverturns no initial/automatic grant simultaneoussecondcheckout denied all4currency+depth+epoch+slot+generation overspend denied heap0 duplicate receipt rejected held exact original then full spent/remaining returned terminalDrop0");
}

#[test]
fn original_host_context_loan_preserves_same_recipient_and_returns_cumulative_wake_once(){
 use semio_framework_job::{JobPayloadAuthority,StepContext,StepBudget,OperationId,Generation};
 let law:serde_json::Value=serde_json::from_str(include_str!("../🧫️fixtures/🔣️.json")).unwrap();let p=&law["policy"];let grant=RetainedCloneGrant{maximum_items:p["items"].as_u64().unwrap()as usize,maximum_copy_bytes:p["copy"].as_u64().unwrap()as usize,maximum_capacity_bytes:p["capacity"].as_u64().unwrap()as usize,maximum_release_bytes:p["release"].as_u64().unwrap()as usize,maximum_depth:p["depth"].as_u64().unwrap()as usize};let operation=OperationId(99205);let generation=Generation(3);let cancel=semio_framework_job::root_cancel_token();let(_,warm)=observe(||drop(vec![0u8;37]));assert_eq!(warm,(37,37));let((mut authority,birth),heap)=observe(||JobPayloadAuthority::admit(operation,generation,grant).unwrap().unwrap());assert_eq!((birth.retained_capacity_bytes,birth.released_bytes),heap);let ledger=GuestRelayWakeReceiptLedger::new();let ledger_pointer=&ledger as*const GuestRelayWakeReceiptLedger;let mut sequence=0;let source=[7u8;41];let mut destination=[0u8;41];let source_pointer=source.as_ptr();let destination_pointer=destination.as_ptr();
 for epoch in [70,71,72]{let mut recipient=RetainedCloneProgress{copied_bytes:23,..Default::default()};let recipient_pointer=&mut recipient as*mut RetainedCloneProgress;let mut context=StepContext::with_payload_authority(operation,generation,StepBudget::new(1,u64::MAX,grant),&cancel,semio_framework_job::logical_now_us,&mut sequence,&mut recipient,&authority).unwrap();let original=context.retained_grant();let(mut loan,heap)=observe(||GuestRelayWakeContextTurn::admit(&ledger,epoch,&mut context).unwrap().unwrap());assert_eq!(heap,(0,0));let quoted=ledger.checkout(7,generation.0).unwrap().unwrap();assert_eq!(quoted.grant,original);assert!(ledger.checkout(8,generation.0).unwrap().is_none());let(done,heap)=observe(||loan.acknowledge().unwrap());assert!(!done);assert_eq!(heap,(0,0));assert_eq!(&ledger as*const _,ledger_pointer);
 let(_,heap)=observe(||destination.copy_from_slice(&source));assert_eq!(heap,(0,0));assert_eq!(destination,source);assert_eq!(source.as_ptr(),source_pointer);assert_eq!(destination.as_ptr(),destination_pointer);let progress=RetainedCloneProgress{copied_items:1,copied_bytes:41,..Default::default()};let rejected=GuestRelayWakeReceipt{epoch,slot:7,generation:generation.0,grant:original,progress:RetainedCloneProgress{copied_bytes:original.maximum_copy_bytes+1,..progress}};let(result,heap)=observe(||ledger.collect(&rejected));assert!(result.is_err());assert_eq!(heap,(0,0));let receipt=GuestRelayWakeReceipt{epoch,slot:7,generation:generation.0,grant:original,progress};assert!(ledger.collect(&receipt).unwrap());let(done,heap)=observe(||loan.acknowledge().unwrap());assert!(done);assert_eq!(heap,(0,0));let(done,heap)=observe(||loan.acknowledge().unwrap());assert!(done);assert_eq!(heap,(0,0));assert!(loan.terminal_is_empty());let(_,heap)=observe(||drop(loan));assert_eq!(heap,(0,0));assert_eq!(context.retained_progress(),RetainedCloneProgress{copied_items:1,copied_bytes:64,..Default::default()});assert_eq!(context.retained_grant().maximum_items,0);assert_eq!(context.retained_grant().maximum_copy_bytes,grant.maximum_copy_bytes-64);drop(context);assert_eq!(&mut recipient as*mut _,recipient_pointer);assert_eq!(recipient.copied_bytes,64);assert!(ledger.begin_turn(epoch,grant).is_err());eprintln!("[DEBUG] actual original Host context epoch={epoch} sameRecipient={recipient_pointer:p} originalLedger={ledger_pointer:p} originalCopy23+actualBorrowed41=64 cumulativeOnce allAxesPreserved noHeap sourcePointersStable noRenewal");}
 let(step,heap)=observe(||authority.close_step(grant).unwrap());assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);assert_eq!(birth.retained_capacity_bytes,step.progress().released_bytes);let(_,heap)=observe(||{drop(authority);drop(ledger)});assert_eq!(heap,(0,0));
}

#[test]
fn original_host_driver_treasury_never_renews_and_rejects_receipts_outside_the_independent_admission_policy(){
 let policy:GuestRelayDriverPolicy=semio_framework_pack_json::from_json_str(include_str!("../📃️policy/🧫️fixtures/🔣️.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let mut original=GuestRelayDriverTreasury::new(policy);let original_pointer=&original as*const _;let initial=original.original_remaining();
 let denied=RetainedCloneProgress{copied_items:1,copied_bytes:policy.admission.maximum_copy_bytes+1,..Default::default()};let(result,heap)=observe(||original.record_admission(denied));assert!(result.is_err());assert_eq!(heap,(0,0));assert_eq!(original.original_remaining(),initial);assert_eq!(&original as*const _,original_pointer);
 let op=semio_framework_job::OperationId(71);let generation=semio_framework_job::Generation(3);let(admitted,heap)=observe(||semio_framework_job::JobPayloadAuthority::admit(op,generation,policy.admission).unwrap());let(mut authority,birth)=admitted.unwrap();assert_eq!((birth.retained_capacity_bytes,birth.released_bytes),heap);original.record_admission(birth).unwrap();
 let source=[83u8;41];let mut destination=[0u8;41];let source_pointer=source.as_ptr();let destination_pointer=destination.as_ptr();let(turn,heap)=observe(||original.begin_turn().unwrap().unwrap());assert_eq!(heap,(0,0));let held_remaining=original.original_remaining();assert!(original.begin_turn().unwrap().is_none());let mismatched=GuestRelayDriverTurnGrant{epoch:turn.epoch+1,..turn};let(result,heap)=observe(||original.return_turn(mismatched,Default::default()));assert!(result.is_err());assert_eq!(heap,(0,0));assert_eq!(original.original_remaining(),held_remaining);
 let(_,heap)=observe(||destination.copy_from_slice(&source));assert_eq!(heap,(0,0));let progress=RetainedCloneProgress{copied_items:1,copied_bytes:41,..Default::default()};original.return_turn(turn,progress).unwrap();assert_eq!(source.as_ptr(),source_pointer);assert_eq!(destination.as_ptr(),destination_pointer);assert_eq!(source,destination);let after=original.original_remaining();assert_eq!(after.maximum_items,initial.maximum_items-birth.copied_items-1);assert_eq!(after.maximum_copy_bytes,initial.maximum_copy_bytes-birth.copied_bytes-41);assert_eq!(after.maximum_capacity_bytes,initial.maximum_capacity_bytes-birth.retained_capacity_bytes);assert_eq!(after.maximum_release_bytes,initial.maximum_release_bytes);
 let(result,heap)=observe(||original.return_turn(turn,progress));assert!(result.is_err());assert_eq!(heap,(0,0));assert_eq!(original.original_remaining(),after);assert!(original.terminal_is_empty());let(step,heap)=observe(||authority.close_step(policy.drive).unwrap());assert_eq!((step.progress().retained_capacity_bytes,step.progress().released_bytes),heap);let release=step.progress();let close_turn=original.begin_turn().unwrap().unwrap();original.return_turn(close_turn,release).unwrap();assert_eq!(original.original_remaining().maximum_release_bytes,initial.maximum_release_bytes-release.released_bytes);assert_eq!(birth.retained_capacity_bytes,release.released_bytes);let(_,heap)=observe(||{drop(authority);drop(original)});assert_eq!(heap,(0,0));eprintln!("[DEBUG] actual original Host finite treasury samePointer admission+sourceCopy41+separateAuthorityRelease paid once, forged+duplicate receipts0heap, no renewal");
}

#[test]
fn original_host_production_driver_keeps_same_finite_treasury_across_all_wake_returns(){
 let policy:GuestRelayDriverPolicy=semio_framework_pack_json::from_json_str(include_str!("../📃️policy/🧫️fixtures/🔣️.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let original=GuestRelayWakeDriver::new(policy);let pointer=&original as*const _;let initial=original.original_remaining().unwrap();let source=[83u8;41];let mut destination=[0u8;41];let source_pointer=source.as_ptr();let destination_pointer=destination.as_ptr();
 for index in 0..initial.maximum_items{
  let(turn,heap)=observe(||original.checkout(7,3).unwrap().unwrap());assert_eq!(heap,(0,0));assert_eq!(turn.epoch,index as u64+1);assert_eq!(turn.grant.maximum_items,policy.wake.maximum_items.min(initial.maximum_items-index));let(second,heap)=observe(||original.checkout(9,5).unwrap());assert!(second.is_none());assert_eq!(heap,(0,0));let actual=RetainedCloneProgress{copied_items:1,copied_bytes:41,..Default::default()};let receipt=GuestRelayWakeReceipt{epoch:turn.epoch,slot:7,generation:3,grant:turn.grant,progress:actual};
  for denied in [GuestRelayWakeReceipt{epoch:turn.epoch+1,..receipt},GuestRelayWakeReceipt{slot:9,..receipt},GuestRelayWakeReceipt{generation:5,..receipt},GuestRelayWakeReceipt{grant:RetainedCloneGrant{maximum_items:turn.grant.maximum_items+1,..turn.grant},..receipt},GuestRelayWakeReceipt{grant:RetainedCloneGrant{maximum_copy_bytes:turn.grant.maximum_copy_bytes+1,..turn.grant},..receipt},GuestRelayWakeReceipt{grant:RetainedCloneGrant{maximum_capacity_bytes:turn.grant.maximum_capacity_bytes+1,..turn.grant},..receipt},GuestRelayWakeReceipt{grant:RetainedCloneGrant{maximum_release_bytes:turn.grant.maximum_release_bytes+1,..turn.grant},..receipt},GuestRelayWakeReceipt{grant:RetainedCloneGrant{maximum_depth:turn.grant.maximum_depth+1,..turn.grant},..receipt}]{let(result,heap)=observe(||original.collect(&denied));assert!(result.is_err());assert_eq!(heap,(0,0));assert_eq!(&original as*const _,pointer);}
  let(_,heap)=observe(||destination.copy_from_slice(&source));assert_eq!(heap,(0,0));let(collected,heap)=observe(||original.collect(&receipt).unwrap());assert!(collected);assert_eq!(heap,(0,0));assert_eq!(source.as_ptr(),source_pointer);assert_eq!(destination.as_ptr(),destination_pointer);assert_eq!(destination,source);let remaining=original.original_remaining().unwrap();assert_eq!(remaining.maximum_items,initial.maximum_items-index-1);assert_eq!(remaining.maximum_copy_bytes,initial.maximum_copy_bytes-41*(index+1));assert_eq!(remaining.maximum_capacity_bytes,initial.maximum_capacity_bytes);assert_eq!(remaining.maximum_release_bytes,initial.maximum_release_bytes);assert_eq!(remaining.maximum_depth,initial.maximum_depth);let(duplicate,heap)=observe(||original.collect(&receipt));assert!(duplicate.is_err());assert_eq!(heap,(0,0));assert_eq!(original.original_remaining().unwrap(),remaining);
 }
 let(turn,heap)=observe(||original.checkout(7,3).unwrap());assert!(turn.is_none());assert_eq!(heap,(0,0));let(_,heap)=observe(||drop(original));assert_eq!(heap,(0,0));eprintln!("[DEBUG] actual original production Host treasury pointer={pointer:p} explicit64wakeTurns actual41copyEach fixed4096phase preserved all5axes forged/duplicate0heap exhaustedNoRenewal terminalDrop0");
}

#[test]
fn original_host_actor_and_wake_returns_share_one_finite_treasury_and_exact_checkout(){
 let policy:GuestRelayDriverPolicy=semio_framework_pack_json::from_json_str(include_str!("../📃️policy/🧫️fixtures/🔣️.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let law:serde_json::Value=serde_json::from_str(include_str!("../📃️policy/⚛️actor/🧫️fixtures/🔣️.json")).unwrap();let original=GuestRelayWakeDriver::new(policy);let pointer=&original as*const _;let operation=semio_framework_job::OperationId(law["operation"].as_u64().unwrap());let generation=semio_framework_job::Generation(law["generation"].as_u64().unwrap());let source=[83u8;41];let mut destination=[0u8;41];let source_pointer=source.as_ptr();let destination_pointer=destination.as_ptr();
 let(denied,heap)=observe(||original.begin_actor_turn(semio_framework_job::OperationId(0),generation));assert!(denied.is_err());assert_eq!(heap,(0,0));assert_eq!(original.original_remaining().unwrap(),policy.operation);
 for row in law["receipts"].as_array().unwrap(){let epoch=row["epoch"].as_u64().unwrap();let spent=RetainedCloneProgress{copied_items:row["spent"][0].as_u64().unwrap()as usize,copied_bytes:row["spent"][1].as_u64().unwrap()as usize,retained_capacity_bytes:row["spent"][2].as_u64().unwrap()as usize,released_bytes:row["spent"][3].as_u64().unwrap()as usize};let before=original.original_remaining().unwrap();
  if row["phase"].as_str().unwrap()=="actor"{let(input,heap)=observe(||original.begin_actor_turn(operation,generation).unwrap().unwrap());assert_eq!(heap,(0,0));assert_eq!((input.operation,input.generation,input.epoch),(operation.0,generation.0,epoch));assert_eq!(input.grant,driver_policy::intersect(policy.drive,before));assert!(original.checkout(7,3).unwrap().is_none());assert!(original.begin_actor_turn(operation,generation).unwrap().is_none());let receipt=input.return_original(spent).unwrap();
   for forged in [semio_framework_actor::RetainedTurnReceipt{input:semio_framework_actor::RetainedTurnInput{operation:operation.0+1,..input},..receipt},semio_framework_actor::RetainedTurnReceipt{input:semio_framework_actor::RetainedTurnInput{generation:generation.0+1,..input},..receipt},semio_framework_actor::RetainedTurnReceipt{input:semio_framework_actor::RetainedTurnInput{epoch:epoch+1,..input},..receipt},semio_framework_actor::RetainedTurnReceipt{remaining:RetainedCloneGrant{maximum_depth:receipt.remaining.maximum_depth+1,..receipt.remaining},..receipt},semio_framework_actor::RetainedTurnReceipt{spent:RetainedCloneProgress{copied_items:input.grant.maximum_items+1,..spent},..receipt}]{let(result,heap)=observe(||original.return_actor_turn(forged));assert!(result.is_err());assert_eq!(heap,(0,0));assert_eq!(original.original_remaining().unwrap(),before);}
   let(_,heap)=observe(||destination.copy_from_slice(&source));assert_eq!(heap,(0,0));let(returned,heap)=observe(||original.return_actor_turn(receipt).unwrap());assert!(returned);assert_eq!(heap,(0,0));let(duplicate,heap)=observe(||original.return_actor_turn(receipt));assert!(duplicate.is_err());assert_eq!(heap,(0,0));
  }else{let(input,heap)=observe(||original.checkout(7,generation.0).unwrap().unwrap());assert_eq!(heap,(0,0));assert_eq!(input.epoch,epoch);assert_eq!(input.grant,driver_policy::intersect(policy.wake,before));assert!(original.begin_actor_turn(operation,generation).unwrap().is_none());let receipt=GuestRelayWakeReceipt{epoch,slot:7,generation:generation.0,grant:input.grant,progress:spent};let(_,heap)=observe(||destination.copy_from_slice(&source));assert_eq!(heap,(0,0));let(returned,heap)=observe(||original.collect(&receipt).unwrap());assert!(returned);assert_eq!(heap,(0,0));}
  assert_eq!(&original as*const _,pointer);assert_eq!(source.as_ptr(),source_pointer);assert_eq!(destination.as_ptr(),destination_pointer);assert_eq!(source,destination);let remaining=original.original_remaining().unwrap();assert_eq!(remaining.maximum_items,before.maximum_items-spent.copied_items);assert_eq!(remaining.maximum_copy_bytes,before.maximum_copy_bytes-spent.copied_bytes);assert_eq!(remaining.maximum_capacity_bytes,before.maximum_capacity_bytes-spent.retained_capacity_bytes);assert_eq!(remaining.maximum_release_bytes,before.maximum_release_bytes-spent.released_bytes);assert_eq!(remaining.maximum_depth,before.maximum_depth);
 }
 let remaining=original.original_remaining().unwrap();assert_eq!([remaining.maximum_items,remaining.maximum_copy_bytes,remaining.maximum_capacity_bytes,remaining.maximum_release_bytes,remaining.maximum_depth],std::array::from_fn::<_,5,_>(|index|law["remaining"][index].as_u64().unwrap()as usize));let(_,heap)=observe(||drop(original));assert_eq!(heap,(0,0));eprintln!("[DEBUG] actual original Host finite shared actor/wake/actor epochs1/2/3 original71/3 exactgrant total3/123/0/0 remaining61/262021/1048576/1048576 depth64 sameTreasury/sourcePointers forged/duplicate/exclusion0heap terminalDrop0");
}
